import json,re
from pathlib import Path
root=Path(__file__).resolve().parents[1];qs=json.loads((root/'data/questions.json').read_text());by={q['id']:q for q in qs}
# Human-authored translations. IDs and code are never translated.
def tr(mod,num,prompt,options=None,exp=None,append=None):
 q=by[f'ccna-{mod:02d}-q{num:03d}'];q['prompt']['fr']=prompt+(('\n\n'+append) if append else '')
 if options is None:options=[o['text']['en'] for o in q['options']]
 assert len(options)==len(q['options']),(q['id'],len(options),len(q['options']))
 for o,v in zip(q['options'],options):o['text']['fr']=v
 if exp is not None:q['explanation']['fr']=exp
 if not q['explanation']['en']:q['explanation']['fr']=''
 q['translationStatus']='validated' if 'fr' in q['explanation'] else 'partial'
def code(mod,num,marker):return by[f'ccna-{mod:02d}-q{num:03d}']['prompt']['en'].split(marker,1)[1].join([marker,''])
tr(3,1,'Quelle affirmation décrit le fonctionnement des machines virtuelles ?', ['Les serveurs virtualisés fonctionnent plus efficacement lorsqu’ils sont physiquement connectés à un commutateur distinct de l’hyperviseur.','L’hyperviseur peut virtualiser des composants physiques, notamment le CPU, la mémoire et le stockage.','Chaque hyperviseur peut prendre en charge une seule machine virtuelle et un seul commutateur logiciel.','L’hyperviseur communique en couche 3 sans ressources supplémentaires.'])
