tr(33,1,'Qu’est-ce qui distingue Cisco DNA Center des outils traditionnels de gestion réseau ?', ['Il sépare les politiques de la configuration réelle des équipements.','Il ne prend pas en charge la haute disponibilité de la gestion en cluster.','Sa conception modulaire permet d’implémenter différentes versions selon les besoins de l’organisation.','Il permet uniquement la découverte automatique dans un déploiement neuf (greenfield).'])
tr(33,2,'Quelles sont deux capacités qui rendent Cisco DNA Center plus extensible que la gestion traditionnelle des équipements de campus ? (Choisissez deux réponses)', ['une conception modulaire pouvant évoluer selon les besoins','des API REST permettant une interaction native avec des applications externes','des adaptateurs compatibles avec toutes les familles Cisco IOS','des SDK permettant l’interaction avec des équipements réseau tiers','des versions personnalisées pour les petites, moyennes et grandes entreprises'])
tr(33,3,'Comment Cisco DNA Center collecte-t-il les données du réseau ?', ['Cisco CU Analyzer collecte les données de chaque équipement sous licence et les transmet au contrôleur.','Les équipements établissent un tunnel IPsec pour échanger des données avec le contrôleur.','Les équipements envoient périodiquement des données via call-home.','Les équipements utilisent des services tels que SNMP, syslog et la télémétrie en continu pour envoyer des données au contrôleur.'])
tr(33,4,'Comment la gestion traditionnelle de campus et Cisco DNA Center diffèrent-ils en matière de déploiement ?', ['La gestion traditionnelle permet de faire évoluer le réseau plus rapidement que Cisco DNA Center.','Cisco DNA Center permet de déployer un réseau plus rapidement que la gestion traditionnelle.','Cisco DNA Center coûte moins cher que la plupart des outils traditionnels.','La gestion traditionnelle déploie généralement correctifs et mises à jour plus rapidement que Cisco DNA Center.'])
tr(33,5,'Quel avantage Cisco DNA Center offre-t-il face à la gestion traditionnelle des équipements de campus ?', ['Il facilite la découverte automatique dans un réseau existant (brownfield).','Il est conçu principalement pour l’assurance réseau.','Il prend en charge la haute disponibilité des fonctions de gestion en cluster.','Il offre de nombreuses extensions, notamment des adaptateurs interdomaines et des SDK tiers.'])
